int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst) {
    int ret = 0;
    int corked = 0;
    size_t total_len = 0;
    struct kvec *iov = rqst->rq_iov;
    int iov_count = rqst->rq_nvec;
    struct page **pages = rqst->rq_pages;
    int npages = rqst->rq_npages;
    int i;

    if (server == NULL || rqst == NULL)
        return -EINVAL;

    /* Cork the socket to ensure the data is sent as a single TCP packet */
    if (set_socket_cork(server->sock, 1) < 0) {
        ret = -EIO;
        goto out;
    }
    corked = 1;

    /* Send the initial SMB request */
    ret = smb_send_kvec(server, iov, iov_count);
    if (ret < 0)
        goto uncork;

    total_len += ret;

    /* Send additional pages if any */
    for (i = 0; i < npages; i++) {
        struct page *page = pages[i];
        int offset = 0;
        int len = PAGE_SIZE;

        while (len > 0) {
            int sent = sock_sendpage(server->sock, page, offset, len, MSG_DONTWAIT);
            if (sent <= 0) {
                ret = -EIO;
                goto uncork;
            }
            total_len += sent;
            offset += sent;
            len -= sent;
        }
    }

    /* Uncork the socket */
uncork:
    if (corked) {
        set_socket_cork(server->sock, 0);
    }

    /* Check if expected length was sent */
    if (total_len != rqst->rq_totallen) {
        server->tcp_status = -1;
        /* Log error and mark for reconnection */
    }

out:
    if (ret < 0) {
        /* Log error message if needed */
    }

    return ret;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
    int ret = 0;
    struct kvec *iov = rqst->rq_iov;
    int iovcnt = rqst->rq_nvec;
    size_t total_len = 0;
    int i;

    for (i = 0; i < iovcnt; i++)
        total_len += iov[i].iov_len;

    if (set_tcp_cork(server->sock, 1) < 0) {
        ret = -EIO;
        goto out;
    }

    ret = smb_send_kvec(server, iov, iovcnt);
    if (ret < 0)
        goto uncork;

    if (ret != iov[0].iov_len) {
        ret = -EIO;
        goto uncork;
    }

    for (i = 1; i < iovcnt; i++) {
        ret = smb_send_kvec(server, &iov[i], 1);
        if (ret < 0)
            goto uncork;
    }

    if (server->total_write != total_len) {
        server->tcp_status = -1;
        ret = -EIO;
        goto uncork;
    }

uncork:
    if (set_tcp_cork(server->sock, 0) < 0 && !ret)
        ret = -EIO;
out:
    if (ret < 0)
        printk(KERN_ERR "Failed to send SMB request: %d\n", ret);
    return ret;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
	int ret = 0;
	int expected_length = 0;
	struct kvec *iov = rqst->rq_iov;
	int iov_count = rqst->rq_nvec;

	/* Prepare the socket by setting TCP_CORK */
	if (set_cork(server, 1) < 0) {
		ret = -EIO;
		goto out;
	}

	/* Send the initial SMB request */
	ret = smb_send_kvec(server, iov, iov_count, 0);
	if (ret < 0)
		goto uncork;

	expected_length = ret;

	/* Iterate through additional pages if present */
	if (rqst->rq_npages > 0) {
		int i;
		for (i = 0; i < rqst->rq_npages; i++) {
			ret = smb_send_kvec(server, &rqst->rq_pages[i], 1, 0);
			if (ret < 0)
				goto uncork;
			expected_length += ret;
		}
	}

	/* Uncork the socket */
	if (set_cork(server, 0) < 0)
		goto out;

	/* Verify the total bytes sent */
	if (expected_length != server->total_bytes_sent) {
		server->tcp_status = 0;
		cifs_dbg(VFS, "Sent different number of bytes than expected\n");
		ret = -EFAULT;
		goto out;
	}

out:
	if (ret < 0)
		cifs_dbg(VFS, "Error sending SMB request: %d\n", ret);
	return ret;

uncork:
	/* Uncork the socket on error */
	if (set_cork(server, 0) < 0)
		cifs_dbg(VFS, "Failed to uncork socket after error\n");
	goto out;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst) {
    int rc = 0;
    int corked = 0;
    size_t total_bytes = 0;
    struct kvec *iov = rqst->rq_iov;
    int iov_len = rqst->rq_nvec;

    if (server == NULL || rqst == NULL)
        return -EINVAL;

    if (set_sock_cork(server->ssocket, true))
        corked = 1;

    rc = smb_send_kvec(server, iov, iov_len, 0);
    if (rc < 0)
        goto out;

    total_bytes += rc;
    iov += iov_len;
    iov_len = rqst->rq_n_pages;

    while (iov_len > 0) {
        rc = smb_send_kvec(server, iov, 1, 0);
        if (rc < 0)
            goto out;
        total_bytes += rc;
        iov++;
        iov_len--;
    }

    if (total_bytes != rqst->rq_len) {
        server->tcp_status = -1;
        rc = -EIO;
    }

out:
    if (corked)
        set_sock_cork(server->ssocket, false);

    if (rc < 0)
        log_smb_send_error(rc);

    return rc;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst) {
    int ret = 0;
    int corked = 0;
    struct kvec *iov;
    unsigned int iovlen;
    ssize_t total_bytes = 0;
    ssize_t bytes_sent;
    int i;

    if (server == NULL || rqst == NULL)
        return -EINVAL;

    iov = rqst->iov;
    iovlen = rqst->iov_len;

    if (set_sock_cork(server->sock, 1))
        goto out;

    corked = 1;
    bytes_sent = smb_send_kvec(server, iov, iovlen);
    if (bytes_sent < 0) {
        ret = bytes_sent;
        goto out;
    }

    total_bytes += bytes_sent;

    for (i = 0; i < rqst->nr_pages; i++) {
        bytes_sent = smb_send_page(server, rqst->pages[i], rqst->offsets[i], rqst->page_sizes[i]);
        if (bytes_sent < 0) {
            ret = bytes_sent;
            goto out;
        }
        total_bytes += bytes_sent;
    }

    if (total_bytes != rqst->total_len) {
        server->tcp_status = TCP_STATUS_NEED_RECONN;
        cifs_dbg(VFS, "send_smb_request: total bytes sent %zd, expected %zd\n", total_bytes, rqst->total_len);
    }

out:
    if (corked)
        set_sock_cork(server->sock, 0);

    if (ret < 0)
        cifs_dbg(ERR, "Failed to send SMB request: error %d\n", ret);

    return ret;
}
